const g=await glob({pattern:"data/orders/**/*"});const t={};const odd=[];for(const f of g.files){const c=(await read({path:f})).content;let o;try{o=JSON.parse(c)}catch(e){odd.push([f,'parse']);continue}
if(o.status!=="paid"){if(o.status!=="pending"&&o.status!=="cancelled")odd.push([f,o.status]);continue}
let s=0;for(const i of o.items)s+=i.qty*i.unitPriceCents;t[o.customer]=(t[o.customer]||0)+s;}
return {odd,top:Object.entries(t).sort((a,b)=>b[1]-a[1])};

